(function(root){
'use strict';
const rarities=['Common','Rare','Super Rare','Ultra Rare','Secret Rare'];
const integer=(n,min,max)=>Number.isSafeInteger(n)&&n>=min&&n<=max;
function defaults(cards){return{prices:Object.fromEntries(rarities.map((r,i)=>[r,{sell:[1,3,7,15,20][i],buy:[5,12,28,60,80][i]}])),offers:rarities.flatMap(r=>cards.filter(c=>c.rarity===r).slice(0,2).map(c=>({id:String(c.id),stock:3}))),customPacks:[]};}
function validate(e,cards){if(e===undefined)return defaults(cards);const ids=new Set(cards.map(c=>String(c.id)));if(!e||typeof e!=='object'||!e.prices||!Array.isArray(e.offers)||e.offers.length>500||!Array.isArray(e.customPacks)||e.customPacks.length>100)throw Error('Configuración de tienda no válida');for(const r of rarities){const p=e.prices[r];if(!p||!integer(p.sell,0,10000)||!integer(p.buy,1,100000)||p.buy<=p.sell)throw Error('El precio de compra debe superar el de venta');}const seen=new Set();for(const o of e.offers){if(!o||!ids.has(o.id)||seen.has(o.id)||!integer(o.stock,0,100000))throw Error('Oferta no válida');seen.add(o.id);}seen.clear();for(const p of e.customPacks){if(!p||typeof p.id!=='string'||!/^custom-[\w-]{1,70}$/.test(p.id)||seen.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>60||!integer(p.cost,1,100000)||!integer(p.size,1,5)||!Array.isArray(p.entries)||!p.entries.length||p.entries.length>cards.length)throw Error('Sobre personalizado no válido');seen.add(p.id);const entries=new Set();let total=0;for(const v of p.entries){if(!v||!ids.has(v.id)||entries.has(v.id)||!integer(v.copies,1,1000)||!integer(v.remaining,0,v.copies))throw Error('Contenido del sobre no válido');entries.add(v.id);total+=v.copies;}if(total<p.size||total>100000)throw Error('Cantidad de cartas del sobre no válida');}return e;}
function price(state,card,kind){return state.economy.prices[card.rarity][kind];}
function protectedCopies(state,id){return Math.max(0,...state.decks.map(d=>d.cards[id]||0));}
function quoteSale(state,cards,items){const byId=new Map(cards.map(c=>[String(c.id),c]));let coins=0,count=0;const seen=new Set();for(const item of items){const c=byId.get(item.id);if(!c||seen.has(item.id)||!integer(item.quantity,1,1e7)||item.quantity>(state.owned[item.id]||0)-protectedCopies(state,item.id))throw Error('No podés vender copias que no tenés o que están en un mazo');seen.add(item.id);coins+=price(state,c,'sell')*item.quantity;count+=item.quantity;}if(!count)throw Error('No hay cartas para vender');if(state.coins+coins>1e9)throw Error('Se alcanzó el límite de monedas');return{coins,count};}
function sell(state,cards,items){const quote=quoteSale(state,cards,items);for(const item of items){state.owned[item.id]-=item.quantity;if(!state.owned[item.id])delete state.owned[item.id];}state.coins+=quote.coins;return quote;}
function excess(state){return Object.entries(state.owned).filter(([,n])=>n>3).map(([id,n])=>({id,quantity:n-3}));}
function buy(state,cards,id){const c=cards.find(c=>String(c.id)===id),offer=state.economy.offers.find(o=>o.id===id);if(!c||!offer||offer.stock<1)throw Error('Esta carta no está disponible en la tienda');const cost=price(state,c,'buy');if(state.coins<cost)throw Error('No tenés monedas suficientes');if((state.owned[id]||0)>=1e7)throw Error('Límite de copias alcanzado');state.coins-=cost;state.owned[id]=(state.owned[id]||0)+1;offer.stock--;return cost;}
function draw(state,cards,id,random){const pack=state.economy.customPacks.find(p=>p.id===id);if(!pack)throw Error('Sobre no disponible');if(state.coins<pack.cost)throw Error('No tenés monedas suficientes');const pool=pack.entries.map(e=>({...e})),result=[];let total=pool.reduce((n,e)=>n+e.remaining,0);if(!total)throw Error('Esta caja especial está agotada');for(let i=0;i<pack.size&&total;i++){let ticket=random(total);if(!integer(ticket,0,total-1))throw Error('Sorteo no válido');for(const e of pool){if(ticket<e.remaining){e.remaining--;total--;result.push(e.id);break;}ticket-=e.remaining;}}const gains={};for(const id of result)gains[id]=(gains[id]||0)+1;for(const[id,n]of Object.entries(gains))if((state.owned[id]||0)+n>1e7)throw Error('Límite de copias alcanzado');pack.entries=pool;state.coins-=pack.cost;for(const[id,n]of Object.entries(gains))state.owned[id]=(state.owned[id]||0)+n;state.packs++;return result;}
root.Economy={defaults,validate,price,protectedCopies,quoteSale,sell,excess,buy,draw};
})(typeof window==='undefined'?globalThis:window);
